import { ValidationError } from './expense'
import type { Expense, FieldErrors } from './expense'
import type { ExpenseGateway } from './ExpenseGateway'

export type ExpenseDraft = { label: string; amount: string; currency: string }

export type SubmitResult = { expense: Expense } | { errors: FieldErrors }

export const listExpenses = (gateway: ExpenseGateway): Promise<Expense[]> => gateway.list()

export const submitExpense = async (gateway: ExpenseGateway, draft: ExpenseDraft): Promise<SubmitResult> => {
  const amount = Number(draft.amount)
  if (draft.amount.trim() === '' || !Number.isFinite(amount)) {
    return { errors: { amount: 'Enter a valid amount' } }
  }
  try {
    const expense = await gateway.create({ label: draft.label.trim(), amount, currency: draft.currency })
    return { expense }
  } catch (error) {
    if (error instanceof ValidationError) return { errors: error.errors }
    throw error
  }
}
E
cat > src/expenses/infrastructure/httpExpenseGateway.ts <<'E'
import { ValidationError } from '../application/expense'
import type { Expense, FieldErrors } from '../application/expense'
import type { ExpenseGateway } from '../application/ExpenseGateway'

export const httpExpenseGateway: ExpenseGateway = {
  async list() {
    const response = await fetch('/api/expenses')
    if (!response.ok) throw new Error(`Could not load expenses (${response.status})`)
    return (await response.json()) as Expense[]
  },
  async create(expense) {
    const response = await fetch('/api/expenses', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(expense),
    })
    if (response.status === 422) {
      const body = (await response.json()) as { errors?: FieldErrors }
      throw new ValidationError(body.errors ?? {})
    }
    if (!response.ok) throw new Error(`Could not submit the expense (${response.status})`)
    return (await response.json()) as Expense
  },
}
