cat > src/expenses/ui/useExpenses/useExpenses.ts <<'E'
import { useCallback, useEffect, useState } from 'react'

import type { Expense, FieldErrors } from '../../application/expense'
import type { ExpenseGateway } from '../../application/ExpenseGateway'
import { listExpenses, submitExpense } from '../../application/expenseUseCases'
import type { ExpenseDraft } from '../../application/expenseUseCases'

export const useExpenses = (gateway: ExpenseGateway) => {
  const [expenses, setExpenses] = useState<Expense[]>([])
  const [loading, setLoading] = useState(true)
  const [loadError, setLoadError] = useState<string | null>(null)
  const [fieldErrors, setFieldErrors] = useState<FieldErrors>({})
  const [submitError, setSubmitError] = useState<string | null>(null)
  const [submitting, setSubmitting] = useState(false)

  useEffect(() => {
    let cancelled = false
    listExpenses(gateway)
      .then((items) => {
        if (!cancelled) setExpenses(items)
      })
      .catch((error: unknown) => {
        if (!cancelled) setLoadError(error instanceof Error ? error.message : 'Could not load expenses')
      })
      .finally(() => {
        if (!cancelled) setLoading(false)
      })
    return () => {
      cancelled = true
    }
  }, [gateway])

  /** Resolves true when the expense was created. */
  const submit = useCallback(
    async (draft: ExpenseDraft): Promise<boolean> => {
      setSubmitting(true)
      setSubmitError(null)
      try {
        const result = await submitExpense(gateway, draft)
        if ('errors' in result) {
          setFieldErrors(result.errors)
          return false
        }
        setFieldErrors({})
        setExpenses((current) => [...current, result.expense])
        return true
      } catch (error) {
        setSubmitError(error instanceof Error ? error.message : 'Could not submit the expense')
        return false
      } finally {
        setSubmitting(false)
      }
    },
    [gateway],
  )

  return { expenses, loading, loadError, fieldErrors, submitError, submitting, submit }
}
