import type { ExpenseGateway } from '../../application/ExpenseGateway'
import { ExpenseForm } from '../ExpenseForm/ExpenseForm'
import { ExpenseList } from '../ExpenseList/ExpenseList'
import { useExpenses } from '../useExpenses/useExpenses'

type Props = { gateway: ExpenseGateway }

export const ExpensesScreen = ({ gateway }: Props) => {
  const { expenses, loading, loadError, fieldErrors, submitError, submitting, submit } = useExpenses(gateway)

  return (
    <main>
      <h1>My expenses</h1>
      {loading ? <p>Loading…</p> : null}
      {loadError ? <p role="alert">{loadError}</p> : null}
      {loading || loadError ? null : <ExpenseList expenses={expenses} />}
      <h2>New expense</h2>
      <ExpenseForm errors={fieldErrors} submitting={submitting} onSubmit={submit} />
      {submitError ? <p role="alert">{submitError}</p> : null}
    </main>
  )
}
