import { useState } from 'react'
import type { FormEvent } from 'react'

import type { FieldErrors } from '../../application/expense'
import type { ExpenseDraft } from '../../application/expenseUseCases'

type Props = {
  errors: FieldErrors
  submitting: boolean
  onSubmit: (draft: ExpenseDraft) => Promise<boolean>
}

const emptyDraft: ExpenseDraft = { label: '', amount: '', currency: 'EUR' }

export const ExpenseForm = ({ errors, submitting, onSubmit }: Props) => {
  const [draft, setDraft] = useState<ExpenseDraft>(emptyDraft)

