      <div>
        <label htmlFor="expense-label">Label</label>
        <input
          id="expense-label"
          value={draft.label}
          aria-invalid={Boolean(errors.label)}
          aria-describedby={errors.label ? 'expense-label-error' : undefined}
          onChange={(event) => setDraft({ ...draft, label: event.target.value })}
        />
        {errors.label ? <p id="expense-label-error" role="alert">{errors.label}</p> : null}
      </div>
      <div>
        <label htmlFor="expense-amount">Amount</label>
        <input
          id="expense-amount"
          inputMode="decimal"
          value={draft.amount}
          aria-invalid={Boolean(errors.amount)}
          aria-describedby={errors.amount ? 'expense-amount-error' : undefined}
          onChange={(event) => setDraft({ ...draft, amount: event.target.value })}
        />
        {errors.amount ? <p id="expense-amount-error" role="alert">{errors.amount}</p> : null}
      </div>
      <div>
        <label htmlFor="expense-currency">Currency</label>
        <input
          id="expense-currency"
          value={draft.currency}
          aria-invalid={Boolean(errors.currency)}
          aria-describedby={errors.currency ? 'expense-currency-error' : undefined}
          onChange={(event) => setDraft({ ...draft, currency: event.target.value.toUpperCase() })}
        />
        {errors.currency ? <p id="expense-currency-error" role="alert">{errors.currency}</p> : null}
      </div>
      <button type="submit" disabled={submitting}>
        {submitting ? 'Submitting…' : 'Submit expense'}
      </button>
    </form>
  )
